action.command:
node -e "
const path = require('path');
const { execSync } = require('child_process');
const data = require('fs').readFileSync(0, 'utf8');
const event = JSON.parse(data);
const saved = event.file || '';
const rel = saved.replace(/\\\\/g, '/').replace(/^.*src\//, '');
const testFile = 'tests/' + rel.replace(/\\.tsx?$/, '.test.ts');
const fs = require('fs');
if (!fs.existsSync(testFile)) { process.exit(0); }
try {
  execSync('npx vitest run ' + testFile, { stdio: 'inherit' });
} catch (e) {
  process.exit(1);
}
"
